/* WHAT A CARD DOES TO A GAME, as the pilots read it: the flags of game/engine/pilots/roles-data.mjs (generated by
 * tools/build-pilot-roles.mjs; its header says what each letter means) and a commander's class. Pure over names, so a
 * pilot, a suite and the Worker read it alike. The room hands a pilot a card's `flags` and `commanderClass` with its other
 * public facts (game/room/room.mjs `factsFrom`); a pilot never reads this module for a seat's hidden cards, because it is
 * handed only names a player at the table could read.
 */
import {CARD_FLAGS, COMMANDER_CLASS} from "./roles-data.mjs";

/* The fold the engine matches names by (game/engine/cards/definitions.mjs): case, accents, punctuation and spacing. */
export const fold = (name) => String(name ?? "").normalize("NFKD").replace(/[̀-ͯ]/g, "").toLowerCase().replace(/[^a-z0-9/ ]+/g, "").replace(/\s+/g, " ").trim();

/** An ENGINE LINK is a doubler, draw engine, token engine, untapper, recursion engine or copier on a permanent. */
export const LINKS = "DWTURC";

export const flagsOf = (name) => CARD_FLAGS[fold(name)] ?? "";
export const commanderClassOf = (name) => COMMANDER_CLASS[fold(name)] ?? 0;
/** Whether a card's flags (a string) include a flag, or any of a set of them. */
export const has = (flags, letters) => [...String(flags ?? "")].some((f) => String(letters).includes(f));
export const isLink = (flags) => has(flags, LINKS);
